def cost(a):
    if not any(a): return 8,0,0,0
    esc=sum(h>=255 for h in a); mode=1; width=0; best=5+len(a)+10*esc
    for w in (1,2,3,4,5,6,7,8,10,12,16,20,24,32):
        n=6+ceil(len(a)*w,8)+10*sum(h>=1<<w for h in a)
        if n<best:best,width,mode=n,w,2
    if mode==2:esc=sum(h>=(1<<width)-1 for h in a)
    return 8*ceil((5+len(a) if mode==1 else 6+ceil(len(a)*width,8))+10*esc,8),mode,width,esc


def frame(a):
    size,mode,w,esc=cost(a); wire=bytearray([mode]); lim=(1<<w)-1 if mode==2 else 255
    if mode==2:
        wire.append(w); x=sum(min(v,lim)<<(w*j) for j,v in enumerate(a)); wire.extend(x.to_bytes(ceil(w*len(a),8),'little'))
    elif mode:wire.extend(min(v,lim) for v in a)
    if mode:
        wire.extend(struct.pack('<I',esc)); wire.extend(b''.join(struct.pack('<HQ',j,v) for j,v in enumerate(a) if v>=lim))
    wire+=bytes(-len(wire)%8);assert len(wire)==size
    return struct.pack('<III',len(a),size,esc)+wire


def geometry(wide):
    narrow=bytearray(wide);q=262144;runs=sl=peak=esc=ext=hbytes=0;last=-1;heads=[]
    for i,(_,h,tag) in enumerate(struct.iter_unpack('<III',wide)):
        b=tag&511;struct.pack_into('<I',narrow,12*i+8,b)
        if i%q==0:sl=48
        sl+=1+16*(h>=255);peak=max(peak,sl);esc+=h>=255;hbytes+=h
        if b!=last:
            heads.append(h);runs+=1;last=b
            if len(heads)==1024:ext+=cost(heads)[0];heads=[]
    if heads:ext+=cost(heads)[0]
    return narrow,(runs,peak,ext,esc,hbytes)


def stalls(cmd,stop,wide):
    packet=12*8192
    for where in ('write','read'):
        p=sp.Popen(cmd,stdin=sp.PIPE,stdout=sp.PIPE,stderr=sp.PIPE,bufsize=0);limit=time.monotonic()+4
        try:
            fcntl.fcntl(p.stdout,fcntl.F_SETPIPE_SZ,4096);os.set_blocking(p.stdin.fileno(),False)
            with selectors.DefaultSelector() as s:
                s.register(p.stdin,selectors.EVENT_WRITE);off=0
                while off<packet:
                    assert s.select(max(0,limit-time.monotonic())), 'blocked fixture feed';off+=os.write(p.stdin.fileno(),wide[off:min(packet,off+16384)])
                s.unregister(p.stdin);s.register(p.stdout,selectors.EVENT_READ);assert s.select(max(0,limit-time.monotonic()))
                if where=='read':
                    out=bytearray()
                    while len(out)<packet:
                        assert s.select(max(0,limit-time.monotonic()));x=os.read(p.stdout.fileno(),packet-len(out));assert x;out+=x
                    # A few bytes of the next row, no EOF. Output of a partial batch is forbidden.
                    os.write(p.stdin.fileno(),wide[packet:packet+7])
            stop.touch();assert p.wait(timeout=2)==75 and b'STOP_OBSERVED' in p.stderr.read()
        finally:
            if p.poll() is None:p.kill();p.wait()
            for f in (p.stdin,p.stdout,p.stderr):f.close()
            stop.unlink(missing_ok=True)


def fixtures(exe,real,blocks):
    rng=random.Random(75131);tests=bad=0
    values=[[0],[1],[255],[2**64-1],[0]*1024,[255]*1024,[1]*1023+[3],[7]*1024,[256,255,0,127]*256]
    for w in (1,3,7,8,10,16,20,32,63):
        for length in (17,1023,1024):values.append([rng.choice([0,1,(1<<w)-2,(1<<w)-1,1<<w]) for _ in range(length)])
    framed=b''.join(map(frame,values));assert sp.run([blocks],input=framed,capture_output=True).returncode==0
    for corrupted in (framed[:-1],framed+b'x',struct.pack('<III',1,8,1)+bytes(8),frame([0])[:-1]+b'X'):
        assert sp.run([blocks],input=corrupted,capture_output=True).returncode!=0
    with tempfile.TemporaryDirectory() as td:
        d=Path(td);raw=d/'raw';stop=d/'stop';until=str(int(time.time())+120)
        for t in (b'!',b'banana\0banana\xff',b'q'*8191,rng.randbytes(8192),rng.randbytes(17773),rng.randbytes(262144+393)):
            raw.write_bytes(t);_,wide=byte_reference(t);narrow,(r,sx,m,esc,h)=geometry(wide);sha=hashlib.sha256(narrow).hexdigest()
            cmd=[exe,'--fixture',raw,stop,until,str(r),str(sx),str(m),sha]
            def run(a,data=wide):return sp.run(a,input=data,capture_output=True,timeout=12)
            z=run(cmd);assert z.returncode==0 and z.stdout==narrow,(t[:10],z.stderr)
            fields=dict(x.split('=') for x in z.stderr.decode().strip().split()[1:]);assert fields['narrow_sha256']==sha and [int(fields[k]) for k in ('rows','final_rank','runs','sxls_peak','m14_payload','sxls_escapes','prefix_bytes')]==[len(t)+1,len(t)+1,r,sx,m,esc,h]
            assert 0<=int(fields['final_compare_bytes'])<=h+65*len(t);tests+=1
            if len(t)>18000:continue
            partial=len(narrow)-(12*(len(t)%8192+1));cases=[]
            for idx,val in [(5,r-1),(6,sx-1),(7,m-1),(8,'a'*64)]:
                c=cmd.copy();c[idx]=str(val);cases.append((c,wide))
            for data in (wide[:-1],wide[:-12],wide+b'x',wide+wide[:12],wide[:8]+b'\x00'*4+wide[12:],wide[:8]+struct.pack('<I',0x80000300)+wide[12:],wide[:8]+struct.pack('<I',0x80100000)+wide[12:]):cases.append((cmd,data))
            if len(wide)>=36:cases.append((cmd,wide[:12]+wide[:12]+wide[24:]))
            for c,data in cases:
                z=run(c,data);assert z.returncode!=0 and len(z.stdout)<=partial and z.stdout==narrow[:len(z.stdout)] and b'FENCED rows=' not in z.stderr;bad+=1
            if len(t)==17773:
                stalls(cmd,stop,wide)
                with (d/'not-a-pipe').open('xb') as out:
                    assert sp.run(cmd,input=wide,stdout=out,stderr=sp.PIPE).returncode!=0 and out.tell()==0
                assert run([real,'--v8-100m',raw,stop,until]).returncode!=0
                assert run([real,*cmd[1:]]).returncode!=0
                assert run([exe,*cmd[1:4],'1',*cmd[5:]]).returncode==75
    print(f'PASS {tests} exact raw row43 -> narrow streams incl SXLS and 8192-row EOF cuts, {bad} refused inputs/caps with final packet withheld, {len(values)} m14 boundary blocks, stalled read/write STOP, wrong rung, file and deadline refusals')


def frozen(exe):
    # No corpus/row access. Hash the original and frame each actual m14 block
    # with its separately stored directory entry. No member copy or row file.
    prod=D/'product.sxi2';before=pin(prod,107519008,PRODUCT);codec,off,size,r=members(prod)[14];assert codec==117 and r==R
    blocks=ceil(r,1024);payload=size-40-16*blocks
    with prod.open('rb') as f:
        f.seek(off);assert struct.unpack('<4QII',f.read(40))==(1024,N+1,40,0,1,117)
        f.seek(off+40+payload);directory=f.read(16*blocks);f.seek(off+40);pos=0
        with sp.Popen([exe],stdin=sp.PIPE,stdout=sp.PIPE,stderr=sp.PIPE) as p:
            for i,(offset,z,esc) in enumerate(struct.iter_unpack('<QII',directory)):
                assert offset==pos and 0<z<=16384 and esc<=1024;pos+=z;b=f.read(z);assert len(b)==z
                p.stdin.write(struct.pack('<III',min(1024,r-1024*i),z,esc)+b)
            assert pos==payload;p.stdin.close();assert p.wait(timeout=10)==0,p.stderr.read();s=p.stdout.read().decode().strip()
    assert prod.stat().st_ctime_ns==before.st_ctime_ns and prod.stat().st_ino==before.st_ino
    assert s.startswith('BLOCK_COST blocks=37742 values=38647521 payload=26563024 escapes=168939 equal_markers=') and s.endswith('zero=0 u8=75 packed=37667');print(s)

